// terralog-crypto — the cryptographic core of Terralog, a travel journal app with
// end-to-end encryption. This file is a faithful, dependency-free extraction of the
// code running in the app (blocs/14-derive.js, blocs/18-coffre.js and the backup
// primitives of blocs/70-exports.js). It produces the same bytes as the app: the test
// vectors in test/vectors.json were generated by the app code itself.
//
// Everything that touches randomness or WebCrypto goes through an injected object, so
// the functions are pure with respect to their inputs and can be tested with fixed IVs.
//
//   const tc = createTerralogCrypto({ subtle: crypto.subtle,
//                                     getRandomValues: (a) => crypto.getRandomValues(a) });
//
// Names used by the app (French) are given in comments, so a reviewer can map each
// function to the app code and to SPEC.md.

const SEP = String.fromCharCode(31);   // unit separator, never typed by a person
const enc = new TextEncoder();
const dec = new TextDecoder();

// ── Constants ─────────────────────────────────────────────────────────────────────────────
export const NOTEBOOK_SALT = 'roadtrip.carnet/v1';   // DERIVE_SEL — fixed on purpose, see SPEC.md
export const NOTEBOOK_ITERATIONS = 600000;           // DERIVE_TOURS
export const NOTEBOOK_BITS = 768;                    // 3 × 32 bytes: link, owner token, master
export const TEXT_PREFIX = 'RTC1:';                  // COFFRE_TXT
export const MEDIA_MARK_V1 = 'RTC1';                 // COFFRE_MARQUE
export const MEDIA_MARK_V2 = 'RTC2';                 // COFFRE_MARQUE_V2 — read by the app, never written
export const MEDIA_HEADER_V2 = 21;                   // 4 mark + 12 IV + 1 epoch + 4 size
export const IV_LENGTH = 12;                         // COFFRE_IV
export const TAG_LENGTH = 16;
export const BACKUP_MARK = 'TLGS1\n';                // SAUVE_MARQUE
export const CONTAINER_MARK = 'TLGC1\n';
export const BACKUP_CHUNK = 1048576;                 // SAUVE_TRANCHE, 1 MiB
export const BACKUP_CHUNK_MAX = 67108864;            // SAUVE_TRANCHE_MAX
export const BACKUP_HEADER_MAX = 1048576;            // SAUVE_ENTETE_MAX
export const BACKUP_ITERATIONS = 600000;             // SAUVE_TOURS
export const BACKUP_ITERATIONS_MIN = 100000;         // bounds applied to an envelope read from a file
export const BACKUP_ITERATIONS_MAX = 1200000;
export const BACKUP_SALT_LENGTH = 16;                // SAUVE_SEL_LEN
export const BACKUP_MIN_PHRASE = 16;                 // characters, counted after normalization

// ── Normalization ─────────────────────────────────────────────────────────────────────────

/** deriveNormaliser — notebook inputs (first name, code, passphrase). */
export function normalizeNotebookInput(t) {
  return String(t || '').normalize('NFKC').trim().toLowerCase().replace(/\s+/g, ' ');
}

/** rtSauveNormaliser — backup passphrase. Same intent, slightly different order. */
export function normalizeBackupPhrase(phrase) {
  let t = String(phrase == null ? '' : phrase);
  try { t = t.normalize('NFKC'); } catch (e) { /* keep as is */ }
  return t.replace(/\s+/g, ' ').trim().toLowerCase();
}

// ── base64url without padding (deriveEnAdresse / rtSauveB64u) ─────────────────────────────

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

export function b64uEncode(bytes) {
  const u = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let s = '', i = 0;
  for (; i + 2 < u.length; i += 3) {
    const n = (u[i] << 16) | (u[i + 1] << 8) | u[i + 2];
    s += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63] + ALPHABET[(n >> 6) & 63] + ALPHABET[n & 63];
  }
  const r = u.length - i;
  if (r === 1) {
    const n = u[i] << 16;
    s += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63];
  } else if (r === 2) {
    const n = (u[i] << 16) | (u[i + 1] << 8);
    s += ALPHABET[(n >> 18) & 63] + ALPHABET[(n >> 12) & 63] + ALPHABET[(n >> 6) & 63];
  }
  return s;
}

/** Strict decoder: throws on any character outside the alphabet or an impossible length. */
export function b64uDecode(s) {
  if (typeof s !== 'string' || !/^[A-Za-z0-9_-]*$/.test(s) || s.length % 4 === 1) {
    throw new Error('base64url');
  }
  const out = new Uint8Array(Math.floor(s.length * 3 / 4));
  let o = 0, acc = 0, bits = 0;
  for (let i = 0; i < s.length; i++) {
    acc = (acc << 6) | ALPHABET.indexOf(s[i]);
    bits += 6;
    if (bits >= 8) { bits -= 8; out[o++] = (acc >> bits) & 255; }
  }
  if (bits > 0 && (acc & ((1 << bits) - 1)) !== 0) throw new Error('base64url');   // non-canonical tail
  return out;
}

function hex(u8) {
  let s = '';
  for (let i = 0; i < u8.length; i++) s += (u8[i] < 16 ? '0' : '') + u8[i].toString(16);
  return s;
}

function concat(...parts) {
  let n = 0;
  for (const p of parts) n += p.length;
  const out = new Uint8Array(n);
  let o = 0;
  for (const p of parts) { out.set(p, o); o += p.length; }
  return out;
}

function u32le(n) {
  const x = Number(n) >>> 0;
  return new Uint8Array([x & 255, (x >>> 8) & 255, (x >>> 16) & 255, (x >>> 24) & 255]);
}
function readU32le(u, pos) {
  return ((u[pos] | (u[pos + 1] << 8) | (u[pos + 2] << 16) | (u[pos + 3] << 24)) >>> 0);
}

function backupNonce(id8, i) {                         // __sauveNonce: fileId(8) || index(4 BE)
  const n = new Uint8Array(12);
  n.set(id8, 0);
  n[8] = (i >>> 24) & 255; n[9] = (i >>> 16) & 255; n[10] = (i >>> 8) & 255; n[11] = i & 255;
  return n;
}
function backupAad(header, i, last) {                  // __sauveAad: header || index(4 BE) || last(1)
  const L = header.length, a = new Uint8Array(L + 5);
  a.set(header, 0);
  a[L] = (i >>> 24) & 255; a[L + 1] = (i >>> 16) & 255; a[L + 2] = (i >>> 8) & 255; a[L + 3] = i & 255;
  a[L + 4] = last ? 1 : 0;
  return a;
}

function asKeyList(keys) {
  const list = Array.isArray(keys) ? keys : [keys];
  if (!list.length || list.some((k) => !k)) throw new Error('no-key');
  return list;
}

// ── The factory ───────────────────────────────────────────────────────────────────────────

export function createTerralogCrypto({ subtle, getRandomValues } = {}) {
  if (!subtle || typeof getRandomValues !== 'function') {
    throw new TypeError('createTerralogCrypto needs { subtle, getRandomValues }');
  }
  // Web Crypto contract: getRandomValues fills the array it is given and returns it.
  const random = (n) => {
    const a = new Uint8Array(n);
    if (getRandomValues(a) !== a) throw new Error('rng');
    return a;
  };
  const sha256 = async (bytes) => new Uint8Array(await subtle.digest('SHA-256', bytes));
  const sha256b64u = async (text) => b64uEncode(await sha256(enc.encode(text)));

  /** Try each key in order; AES-GCM rejects a wrong key cleanly (__coffreEssayer). */
  async function tryKeys(keys, attempt) {
    let last = null;
    for (const k of asKeyList(keys)) {
      try { return await attempt(k); } catch (e) { last = e; }
    }
    throw last || new Error('decrypt');
  }

  // ── 1. Notebook derivation (rtDeriverCarnet) ──────────────────────────────────────────
  /**
   * First name + 6-digit code + passphrase → notebook address, owner token, master key.
   * PBKDF2-HMAC-SHA256, fixed salt, 600 000 iterations, 768 bits cut in three 32-byte parts.
   * Returns { link, ownerToken, master } (app: { lien, jeton, maitre }), base64url.
   */
  async function deriveNotebook(firstName, code, passphrase) {
    const material = [normalizeNotebookInput(firstName), normalizeNotebookInput(code),
                      normalizeNotebookInput(passphrase)].join(SEP);
    const base = await subtle.importKey('raw', enc.encode(material), 'PBKDF2', false, ['deriveBits']);
    const o = new Uint8Array(await subtle.deriveBits(
      { name: 'PBKDF2', hash: 'SHA-256', salt: enc.encode(NOTEBOOK_SALT), iterations: NOTEBOOK_ITERATIONS },
      base, NOTEBOOK_BITS));
    return { link: b64uEncode(o.slice(0, 32)),
             ownerToken: b64uEncode(o.slice(32, 64)),
             master: b64uEncode(o.slice(64, 96)) };
  }

  // ── 2. Per-trip address (rtDeriverVoyage) ─────────────────────────────────────────────
  /**
   * The address of one trip and its owner token, from the master key and the trip identity
   * frozen at its creation (internal name, creation time). One SHA-256 each, no stretching:
   * the master key is already 256 bits of PBKDF2 output.
   */
  async function deriveTrip(master, tripName, created) {
    if (!master) throw new Error('no-master');
    const base = [master, normalizeNotebookInput(tripName || ''), String(created || '')].join(SEP);
    return { link: await sha256b64u('lien' + SEP + base),
             ownerToken: await sha256b64u('jeton' + SEP + base) };
  }

  // ── 3. Reading material (rtDeriverMatiereLectureV2 / V1) ──────────────────────────────
  /**
   * The value carried after `#k=` in a share link. v2 is per notebook (master + notebook
   * address, the `?c=` of the page); v1 depended on the master key only and is still read.
   */
  async function readingMaterialV2(master, notebookAddress) {
    if (!master || !notebookAddress) throw new Error('no-master');
    return sha256b64u('lecture/v2' + SEP + master + SEP + notebookAddress);
  }
  async function readingMaterialV1(master) {
    if (!master) throw new Error('no-master');
    return sha256b64u('lecture/v1' + SEP + master);
  }

  // ── 4. Content key (coffreCleDepuis) ──────────────────────────────────────────────────
  /**
   * AES-256-GCM key = SHA-256('coffre/v1' ‖ 0x1F ‖ material). Not extractable.
   * A single hash is enough ONLY because `material` is already 256 bits of PBKDF2 / SHA-256
   * output (a reading material). Never call this with a password: there is no salt and no cost.
   */
  async function contentKey(material) {
    if (!material) throw new Error('no-material');
    const raw = await sha256(enc.encode('coffre/v1' + SEP + material));
    return subtle.importKey('raw', raw, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']);
  }

  // ── 5. Text fields (coffreChiffrerTexte / coffreDechiffrerTexte) ──────────────────────
  /**
   * 'RTC1:' + base64url(IV(12) ‖ AES-GCM(text) ‖ tag(16)). No associated data.
   * An empty value stays empty (null / undefined / '' are returned unchanged).
   * Difference with the app: without a key the app's coffreChiffrerTexte returned the text
   * unchanged (and did the same if encryption failed); since the November 2026 version the app refuses to send
   * such a value (couche-relais.js, fuiteDeClair). Here it simply throws.
   */
  async function encryptText(key, text) {
    if (text === null || text === undefined || text === '') return text;
    if (!key) throw new Error('no-key');
    const iv = random(IV_LENGTH);
    const ct = new Uint8Array(await subtle.encrypt({ name: 'AES-GCM', iv }, key, enc.encode(String(text))));
    return TEXT_PREFIX + b64uEncode(concat(iv, ct));
  }

  function isEncryptedText(value) {
    return typeof value === 'string' && value.indexOf(TEXT_PREFIX) === 0;
  }

  /**
   * Throws 'not-encrypted', 'base64url', 'short' or the GCM error. `keys`: one key or a list.
   * Difference with the app: the app returns a non-prefixed value as is (text written before
   * encryption existed) and shows a placeholder when decryption fails.
   */
  async function decryptText(keys, value) {
    if (!isEncryptedText(value)) throw new Error('not-encrypted');
    const u = b64uDecode(value.slice(TEXT_PREFIX.length));
    if (u.length < IV_LENGTH + TAG_LENGTH) throw new Error('short');
    const iv = u.slice(0, IV_LENGTH), body = u.slice(IV_LENGTH);
    const clear = await tryKeys(keys, (k) => subtle.decrypt({ name: 'AES-GCM', iv }, k, body));
    return dec.decode(clear);
  }

  // ── 6. Media, format RTC1 (coffreChiffrerBlob) — the format the app writes ─────────────
  /**
   * 'RTC1'(4) ‖ IV(12) ‖ AES-GCM( len(1) ‖ type ‖ bytes ) ‖ tag. No associated data.
   * The MIME type is inside the ciphertext. The app cuts the type at 120 characters; a type
   * whose UTF-8 form exceeds 255 bytes cannot be written in one length byte and is refused here.
   * Difference with the app: the app works on a Blob and falls back to blob.type when `type` is
   * empty; here there is no Blob, so the caller passes the type it wants written.
   */
  async function encryptMediaV1(key, bytes, type) {
    if (!key) throw new Error('no-key');
    const t = enc.encode(String(type || 'application/octet-stream').slice(0, 120));
    if (t.length > 255) throw new Error('type-too-long');
    const raw = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    const clear = concat(new Uint8Array([t.length]), t, raw);
    const iv = random(IV_LENGTH);
    const ct = new Uint8Array(await subtle.encrypt({ name: 'AES-GCM', iv }, key, clear));
    return concat(enc.encode(MEDIA_MARK_V1), iv, ct);
  }

  // ── 7. Media, format RTC2 (coffreChiffrerBlobV2) — read by the app, never written ──────
  /**
   * Header (21 bytes, authenticated as AAD): 'RTC2' ‖ IV(12) ‖ epoch(1) ‖ size(4, big-endian).
   * Body: AES-GCM( len(1) ‖ type ‖ bytes ), AAD = the 21 header bytes.
   */
  async function encryptMediaV2(key, bytes, type, epoch) {
    if (!key) throw new Error('no-key');
    const t = enc.encode(String(type || 'application/octet-stream')).subarray(0, 200);
    const raw = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    const clear = concat(new Uint8Array([t.length]), t, raw);
    const iv = random(IV_LENGTH);
    const e = (epoch === undefined || epoch === null) ? 0 : (epoch & 255);
    const n = raw.length;
    const header = new Uint8Array(MEDIA_HEADER_V2);
    header.set(enc.encode(MEDIA_MARK_V2), 0);
    header.set(iv, 4);
    header[16] = e;
    header[17] = (n >>> 24) & 255; header[18] = (n >>> 16) & 255;
    header[19] = (n >>> 8) & 255;  header[20] = n & 255;
    const ct = new Uint8Array(await subtle.encrypt({ name: 'AES-GCM', iv, additionalData: header }, key, clear));
    return concat(header, ct);
  }

  /** coffreLireEntete — null when the bytes are not a vault block (the app then serves them as is). */
  function readMediaHeader(u) {
    if (!u || u.length < 17) return null;
    const mark = String.fromCharCode(u[0], u[1], u[2], u[3]);
    if (mark === MEDIA_MARK_V1) return { format: MEDIA_MARK_V1, iv: u.subarray(4, 16), body: u.subarray(16) };
    if (mark === MEDIA_MARK_V2) {
      if (u.length < MEDIA_HEADER_V2) return null;
      return { format: MEDIA_MARK_V2, header: u.subarray(0, MEDIA_HEADER_V2), iv: u.subarray(4, 16),
               epoch: u[16], size: (u[17] * 16777216) + (u[18] << 16) + (u[19] << 8) + u[20],
               body: u.subarray(MEDIA_HEADER_V2) };
    }
    return null;
  }

  /** Decrypts RTC1 or RTC2. Returns { format, type, bytes, epoch? }. Throws 'format' otherwise. */
  async function decryptMedia(keys, bytes) {
    const u = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    const h = readMediaHeader(u);
    if (!h) throw new Error('format');
    const params = h.format === MEDIA_MARK_V2
      ? { name: 'AES-GCM', iv: h.iv, additionalData: h.header }
      : { name: 'AES-GCM', iv: h.iv };
    const clear = new Uint8Array(await tryKeys(keys, (k) => subtle.decrypt(params, k, h.body)));
    const n = clear[0];
    const type = dec.decode(clear.subarray(1, 1 + n)) || 'application/octet-stream';
    if (h.format === MEDIA_MARK_V1) {
      return { format: h.format, type, bytes: clear.slice(1 + n) };
    }
    // The size field is trusted only after GCM, and never beyond what is there.
    const available = clear.length - 1 - n;
    const size = (h.size > 0 && h.size <= available) ? h.size : available;
    return { format: h.format, type, epoch: h.epoch, bytes: clear.slice(1 + n, 1 + n + size) };
  }

  // ── 8. Backups: key envelope (__sauveEnvelopper / __sauveOuvrirBrut) ───────────────────
  async function backupKek(phrase, salt, iterations) {
    const base = await subtle.importKey('raw', enc.encode(normalizeBackupPhrase(phrase)), 'PBKDF2', false, ['deriveKey']);
    return subtle.deriveKey({ name: 'PBKDF2', hash: 'SHA-256', salt, iterations },
                            base, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
  }

  /** A fresh 32-byte content key K for backups (drawn once, at activation). */
  function newBackupKey() { return random(32); }

  /**
   * Wraps K under the passphrase: KEK = PBKDF2-SHA256(phrase, salt 16, 600 000), then
   * AES-GCM(K). Salt and IV are fresh for each envelope. Returns { sel, tours, iv, ct }.
   * The 16-character minimum is checked by the app one level up (rtSauveActiver); it is
   * checked here so the module cannot wrap a key under a shorter phrase.
   */
  async function wrapBackupKey(rawKey, phrase) {
    if (!(rawKey instanceof Uint8Array) || rawKey.length !== 32) throw new Error('key');
    if (normalizeBackupPhrase(phrase).length < BACKUP_MIN_PHRASE) throw new Error('phrase');
    const salt = random(BACKUP_SALT_LENGTH);
    const iv = random(IV_LENGTH);
    const kek = await backupKek(phrase, salt, BACKUP_ITERATIONS);
    const ct = new Uint8Array(await subtle.encrypt({ name: 'AES-GCM', iv }, kek, rawKey));
    return { sel: b64uEncode(salt), tours: BACKUP_ITERATIONS, iv: b64uEncode(iv), ct: b64uEncode(ct) };
  }

  /** Returns K (32 bytes) or null when the phrase is wrong or the envelope damaged. */
  async function unwrapBackupKey(envelope, phrase) {
    try {
      if (!envelope || !envelope.sel || !envelope.iv || !envelope.ct) return null;
      const salt = b64uDecode(envelope.sel), iv = b64uDecode(envelope.iv), ct = b64uDecode(envelope.ct);
      if (salt.length !== BACKUP_SALT_LENGTH || iv.length !== IV_LENGTH || ct.length < 32) return null;
      // The iteration count comes from a file, so from a stranger: it is bounded.
      const it = Math.min(BACKUP_ITERATIONS_MAX, Math.max(BACKUP_ITERATIONS_MIN, Number(envelope.tours) || BACKUP_ITERATIONS));
      const kek = await backupKek(phrase, salt, it);
      const raw = new Uint8Array(await subtle.decrypt({ name: 'AES-GCM', iv }, kek, ct));
      return raw.length === 32 ? raw : null;
    } catch (e) { return null; }
  }

  async function importBackupKey(rawKey) {
    return subtle.importKey('raw', rawKey, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']);
  }

  // ── 9. Backups: the .tlg file (rtSauveChiffrerFichier / rtSauveDechiffrerFichier) ─────
  /**
   * 'TLGS1\n' ‖ uint32 LE header length ‖ header (JSON, UTF-8, in clear) ‖ chunks.
   * Chunk i: AES-GCM of 1 MiB of clear, nonce = fileId(8) ‖ i(4 BE),
   *          AAD = exact header bytes ‖ i(4 BE) ‖ last-chunk flag(1).
   * A zero-byte file still has one (empty) chunk, so the header is always authenticated.
   * This reference keeps the whole output in memory; the app writes large files chunk by chunk
   * (rtSauveChiffrerVers), producing the same bytes.
   */
  async function encryptBackupFile(key, bytes, { kind, envelope, uid } = {}) {
    if (!key) throw new Error('no-key');
    const raw = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    const size = raw.length;
    const nb = size === 0 ? 1 : Math.ceil(size / BACKUP_CHUNK);
    const id = random(8);
    const header = {
      format: 'terralog-sauvegarde',
      version: 1,
      genre: kind === 'media' ? 'media' : 'manifeste',
      tranche: BACKUP_CHUNK,
      idFichier: b64uEncode(id),
      nbTranches: nb,
      tailleClair: size,
      enveloppe: envelope
    };
    if (uid != null && uid !== '') header.uid = String(uid).slice(0, 64);
    const headerBytes = enc.encode(JSON.stringify(header));
    const parts = [enc.encode(BACKUP_MARK), u32le(headerBytes.length), headerBytes];
    for (let i = 0; i < nb; i++) {
      const clear = raw.subarray(i * BACKUP_CHUNK, Math.min(size, (i + 1) * BACKUP_CHUNK));
      parts.push(new Uint8Array(await subtle.encrypt(
        { name: 'AES-GCM', iv: backupNonce(id, i), additionalData: backupAad(headerBytes, i, i === nb - 1) },
        key, clear)));
    }
    return concat(...parts);
  }

  /** rtSauveLireEntete — { header, headerBytes, start } or null. Reads the envelope without a key. */
  function readBackupHeader(bytes) {
    const u = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    if (u.length < BACKUP_MARK.length + 4) return null;
    if (dec.decode(u.subarray(0, BACKUP_MARK.length)) !== BACKUP_MARK) return null;
    const len = readU32le(u, BACKUP_MARK.length);
    if (!len || len > BACKUP_HEADER_MAX) return null;
    const start = BACKUP_MARK.length + 4 + len;
    if (u.length < start) return null;
    const headerBytes = u.slice(BACKUP_MARK.length + 4, start);
    let header;
    try { header = JSON.parse(dec.decode(headerBytes)); } catch (e) { return null; }
    if (!header || header.format !== 'terralog-sauvegarde' || Number(header.version) !== 1) return null;
    return { header, headerBytes, start };
  }

  /**
   * Throws 'header', 'swapped', 'truncated', 'tampered' (wrong key or a byte changed) or 'length'.
   * Pass `expectedUid` when reading a media file: all media of a backup share one key, so a
   * valid file of ANOTHER media would otherwise decrypt without error. The app checks the same
   * thing before decrypting (rtSauveOuvrirDossier / rtSauveOuvrirConteneur, error 'echange').
   * Error names differ from the app's ('entete', 'echange', 'tronque', 'altere', 'longueur').
   */
  async function decryptBackupFile(key, bytes, { expectedUid } = {}) {
    if (!key) throw new Error('header');
    const u = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    const r = readBackupHeader(u);
    if (!r) throw new Error('header');
    const e = r.header;
    if (expectedUid !== undefined && e.uid !== expectedUid) throw new Error('swapped');
    let id;
    try { id = b64uDecode(String(e.idFichier)); } catch (x) { throw new Error('header'); }
    if (id.length !== 8) throw new Error('header');
    const chunk = Number(e.tranche) || BACKUP_CHUNK;
    const nb = Number(e.nbTranches), size = Number(e.tailleClair);
    if (!(chunk > 0) || chunk > BACKUP_CHUNK_MAX) throw new Error('header');
    if (!(nb >= 1) || !(size >= 0) || nb > 1000000) throw new Error('header');
    let pos = r.start;
    const out = [];
    for (let i = 0; i < nb; i++) {
      const clearLen = Math.min(chunk, size - i * chunk);
      if (clearLen < 0) throw new Error('truncated');
      const len = clearLen + TAG_LENGTH;
      if (pos + len > u.length) throw new Error('truncated');
      const piece = u.subarray(pos, pos + len);
      pos += len;
      try {
        out.push(new Uint8Array(await subtle.decrypt(
          { name: 'AES-GCM', iv: backupNonce(id, i), additionalData: backupAad(r.headerBytes, i, i === nb - 1) },
          key, piece)));
      } catch (x) { throw new Error('tampered'); }
    }
    if (pos !== u.length) throw new Error('length');
    return concat(...out);
  }

  // ── 10. Server-side fingerprints (relais/liens.php, relais/proprietaire.php) ───────────
  // The relay stores no link and no token, only these. Given here so the claim can be checked.
  /** lien_empreinte: hex SHA-256 of the link, NOT salted (see SPEC.md, limits). */
  async function linkFingerprint(link) { return hex(await sha256(enc.encode(String(link)))); }
  /** prop_empreinte: hex SHA-256(salt ‖ token), salt = 32 hex characters drawn per notebook. */
  async function ownerTokenFingerprint(token, saltHex) {
    return hex(await sha256(enc.encode(String(saltHex) + String(token))));
  }

  return {
    deriveNotebook, deriveTrip, readingMaterialV2, readingMaterialV1, contentKey,
    encryptText, decryptText, isEncryptedText,
    encryptMediaV1, encryptMediaV2, readMediaHeader, decryptMedia,
    newBackupKey, wrapBackupKey, unwrapBackupKey, importBackupKey,
    encryptBackupFile, readBackupHeader, decryptBackupFile,
    linkFingerprint, ownerTokenFingerprint
  };
}

// ── Backup container (no cryptography: it only concatenates .tlg files) ───────────────────
/** 'TLGC1\n' ‖ uint32 LE count ‖ (uint32 LE length ‖ bytes)… — the manifest comes first. */
export function packContainer(files) {
  if (!Array.isArray(files) || !files.length) throw new Error('empty');   // the manifest is always there
  const parts = [enc.encode(CONTAINER_MARK), u32le(files.length)];
  for (const f of files) parts.push(u32le(f.length), f);
  return concat(...parts);
}
export function unpackContainer(bytes) {
  const u = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  if (u.length < 10 || dec.decode(u.subarray(0, 6)) !== CONTAINER_MARK) throw new Error('header');
  const nb = readU32le(u, 6);
  if (!(nb >= 1) || nb > 1000000) throw new Error('header');
  const out = [];
  let pos = 10;
  for (let i = 0; i < nb; i++) {
    if (pos + 4 > u.length) throw new Error('truncated');
    const L = readU32le(u, pos); pos += 4;
    if (pos + L > u.length) throw new Error('truncated');
    out.push(u.slice(pos, pos + L)); pos += L;
  }
  return out;
}
